package com.eventforge.notification;
import com.eventforge.domain.User; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController {private final NotificationService service; public NotificationController(NotificationService service){this.service=service;} @GetMapping public Page<NotificationDto> list(@AuthenticationPrincipal User user,Pageable pageable){return service.list(user.getId(),pageable);} @PatchMapping("/{id}/read") public NotificationDto read(@PathVariable UUID id,@AuthenticationPrincipal User user){return service.markRead(id,user.getId());}}
